print("============================================================")
print("Photoshop Touch Mach-O symbol import")
print("Symbols:", len(symbols))
print("============================================================")

fm = currentProgram.getFunctionManager()
st = currentProgram.getSymbolTable()
af = currentProgram.getAddressFactory()

for value, raw_name in symbols:
    try:
        addr = af.getDefaultAddressSpace().getAddress(value)

        if addr is None or not currentProgram.getMemory().contains(addr):
            missing_memory += 1
            continue

        name = clean_name(raw_name)

        func = fm.getFunctionAt(addr)

        if func is not None:
            old = func.getName()

            # Promote original symbol if the current name is autogenerated.
            if is_auto_name(old):
                try:
                    func.setName(name, SourceType.IMPORTED)
                    renamed_functions += 1
                except Exception as e:
                    # Name collision: keep function and create a secondary
                    # original-name label if possible.
                    try:
                        st.createLabel(
                            addr,
                            name,
                            SourceType.IMPORTED
                        )
                        created_labels += 1
                        conflicts += 1
                    except:
                        failures += 1

            elif old == name:
                preserved_existing += 1

            else:
                # Preserve deliberate/manual/existing name, but attach
                # original Mach-O name as another symbol when possible.
                try:
                    existing = st.getSymbols(addr)
                    already = False

                    while existing.hasNext():
                        s = existing.next()

                        if s.getName() == name:
                            already = True
                            break

                    if already:
                        preserved_existing += 1
                    else:
                        st.createLabel(
                            addr,
                            name,
                            SourceType.IMPORTED
                        )
                        created_labels += 1

                except:
                    failures += 1

        else:
            # Symbol may represent data, an internal code label, a vtable,
            # Objective-C metadata, etc. Don't manufacture a function.
            try:
                existing = st.getSymbols(addr)
                already = False

                while existing.hasNext():
                    s = existing.next()

                    if s.getName() == name:
                        already = True
                        break

                if already:
                    preserved_existing += 1
                else:
                    st.createLabel(
                        addr,
                        name,
                        SourceType.IMPORTED
                    )
                    created_labels += 1

            except:
                failures += 1

    except Exception as e:
        failures += 1
        print(
            "FAILED 0x%08X %s : %s"
            % (value, raw_name, str(e))
        )

print()
print("============================================================")
print("IMPORT COMPLETE")
print("============================================================")
print("Functions renamed :", renamed_functions)
print("Labels created    :", created_labels)
print("Already present   :", preserved_existing)
print("Name conflicts    :", conflicts)
print("Outside memory    :", missing_memory)
print("Failures          :", failures)
print("============================================================")
print()
print("NOTE:")
print("C++ symbols remain in their original Itanium-mangled spelling.")
print("Ghidra can demangle them separately using its Demangler.")
